-- Jednorazowy import projektu OE10 (WITPiS, umowa nr 91719; stan 31.10.2026):
-- • HRF z arkusza „WITPIS- HRF ENVCHECK.xlsx” — pozycja trwa przez miesiąc, w którym HRF ma jej kwotę
--   (kwota → wartość Etapu [W]); grupy obejmują zakres pozycji podrzędnych. Pominięte puste grupy 2.1.2 i 2.4.1;
--   „[09]” ma kod 2.1.1.0 (w HRF zdublowany 2.1.1.1); „Rozbiórki” 2.6.6 pod Etapem 2 (brak 2.6 w HRF).
-- • zadania wewnętrzne z notatek Kamila („TODO WITPIS” + „TODO V2”, bez duplikatów) pod zadaniami HRF,
--   z terminem zadania nadrzędnego; przekreślone = 100%, „w trakcie” = 50%; MK = Michał Kruk, KJ = Kamil Jankowski.
-- Nic nie robi, gdy projektu OE10 nie ma albo ma już zadania HRF. Dzień „0” (gdy pusty) = 01.09.2025 — pierwszy miesiąc HRF.
DO $$
DECLARE
  pid uuid;
  dz date;
BEGIN
  SELECT id, coalesce(day_zero_date, DATE '2025-09-01') INTO pid, dz FROM projects WHERE lower(code) = 'oe10' AND deleted_at IS NULL;
  IF pid IS NULL THEN
    RAISE NOTICE 'OE10: brak projektu — import pominięty';
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM hrf_tasks WHERE project_id = pid AND deleted_at IS NULL) THEN
    RAISE NOTICE 'OE10: projekt ma już zadania HRF — import pominięty';
    RETURN;
  END IF;
  UPDATE projects SET day_zero_date = dz WHERE id = pid AND day_zero_date IS NULL;

  CREATE TEMP TABLE oe10_formal (code text, name text, parent_code text, party text, start_date date, end_date date, contract_value numeric, acceptance boolean, notes text, ord int) ON COMMIT DROP;

  -- Pozycje bez terminu: dzień „0”, 1 dzień (do uzupełnienia).
  SELECT pid, f.code, f.name, f.party,
         coalesce(f.start_date - dz, 0), coalesce(f.end_date - f.start_date + 1, 1),
         coalesce(f.start_date, dz), coalesce(f.end_date, dz),
         f.contract_value, f.acceptance, f.acceptance, f.notes, f.ord
  FROM oe10_formal f;
  UPDATE hrf_tasks t SET parent_id = p.id
  FROM oe10_formal f JOIN hrf_tasks p ON p.project_id = pid AND p.code = f.parent_code AND p.deleted_at IS NULL
  WHERE t.project_id = pid AND t.code = f.code AND t.deleted_at IS NULL;

  CREATE TEMP TABLE oe10_internal (id uuid DEFAULT gen_random_uuid(), parent_code text, name text, pct smallint, mk boolean, kj boolean, notes text, ord int) ON COMMIT DROP;

  -- created_at rośnie z kolejnością — lista zachowuje układ notatek przy tym samym terminie.
  SELECT i.id, pid, t.id, i.name, t.planned_start, t.planned_end, i.pct, i.notes, now() + i.ord * interval '1 millisecond', now()
  FROM oe10_internal i JOIN hrf_tasks t ON t.project_id = pid AND t.code = i.parent_code AND t.deleted_at IS NULL;

  -- Osoby po imieniu i nazwisku; bez konta — zadanie zostaje bez przypisania.
  SELECT i.id, u.id
  FROM oe10_internal i
  JOIN users u ON u.deleted_at IS NULL AND (
    (i.mk AND lower(u.name) = 'michał kruk') OR (i.kj AND lower(u.name) = 'kamil jankowski'))
  ON CONFLICT DO NOTHING;
END $$;
